// Integral Promotions (C++ Standard 4.5)
// Ensures operations use sufficient precision (int or unsigned int).

short s = 500;
unsigned char uc = 2;

// Rule: s and uc are promoted to int before multiplication
auto result = s * uc; // Type of result is int, not short/char

// Example with literal constant type deduction:
// Type of 'c + 1' is int (c promotes to int)
char c = 10;
int x = c + 1;

// Promotion applies to scoped enumerations with smaller bases:
enum class Status : short { Ready = 1 };

// The value Status::Ready promotes to int before addition
int i = static_cast<int>(Status::Ready) + 1;
// i requires cast because Status is strong-typed (C++11)
// but underlying arithmetic happens in int scope.
